//! 🧳️ Typed clone-cursor custody exposes genuine selected quotes and controlled partial-owner closure.
use super::{RetainedClone,RetainedCloneCursor,RetainedCloneRef,RetainedCloneGrant,RetainedCloneStep,RetainedCloneProgress};
use crate::{ValueError,RetirementDemand,retirement::{RetireOwned,RetirementCursor,RetirementStep}};
use std::mem::ManuallyDrop;

pub struct RetainedCloneOwner<T:RetainedClone>{cursor:ManuallyDrop<T::Cursor>,closing:bool,close_action:Option<(crate::OriginalEffectInvocationIdentity,u8,usize)>}
impl<T:RetainedClone> Default for RetainedCloneOwner<T>{fn default()->Self{Self{cursor:ManuallyDrop::new(T::retained_clone_cursor()),closing:false,close_action:None}}}
impl<T:RetainedClone> RetainedCloneOwner<T>{
 /// 🧺️ Keeps the exact admitted typed cursor and all its retained ownership.
 pub fn from_cursor(cursor:T::Cursor)->Self{Self{cursor:ManuallyDrop::new(cursor),closing:false,close_action:None}}
 pub fn advance_demands(&self,source:RetainedCloneRef<'_,T>,copy:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{self.cursor.advance_demands(source,copy,maximum_work_units)}
 /// ⛽️ Quotes the selected original child work.
 pub fn advance_work_demand(&self,source:RetainedCloneRef<'_,T>,copy:usize,maximum_work_units:u64)->Result<u64,ValueError>{self.cursor.advance_work_demand(source,copy,maximum_work_units)}
 pub fn advance_into<'reply>(&mut self,source:RetainedCloneRef<'_,T>,body:usize,maximum:u64,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if self.closing{return Err(ValueError::invariant("clone owner is closing"))}self.cursor.advance_into(source,body,maximum,effect,reply)}
 pub fn recover_advance_into<'reply>(&mut self,source:RetainedCloneRef<'_,T>,body:usize,maximum:u64,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.cursor.recover_advance_into(source,body,maximum,effect,reply)}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{self.cursor.take_demand()}
 pub fn take<'reply>(&mut self,output:&mut Option<T>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>{if self.closing{return Err(ValueError::invariant("clone owner is closing"))}self.cursor.take(output,effect,reply)}
 pub fn recover_take<'reply>(&mut self,output:&mut Option<T>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>{self.cursor.recover_take(output,effect,reply)}
 /// 🚦️ Reports that the defining typed cursor holds a complete output awaiting `take`.
 pub fn output_ready(&self)->bool{!self.closing&&self.cursor.output_ready()}
 pub fn terminal_is_empty(&self)->bool{self.close_action.is_none()&&self.cursor.terminal_is_empty()}
 pub fn selected_close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.close_action.is_some_and(|(_,_,selected)|selected!=body){return Err(ValueError::invariant("clone owner close body changed"))}if !self.closing{return Ok(RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()})}if !self.cursor.close_started(){return self.cursor.begin_close_demand()}self.cursor.close_demands(body)}
 /// ⛽️ Parent intent and child start are separate original actions, each admitting one-work loans.
 pub fn selected_close_work_demand(&self,body:usize)->Result<u64,ValueError>{if self.close_action.is_some_and(|(_,_,selected)|selected!=body){return Err(ValueError::invariant("clone owner close body changed"))}if !self.closing{return Ok(1)}if !self.cursor.close_started(){return self.cursor.begin_close_work_demand()}self.cursor.close_work_demand(body)}
 pub fn close_into<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if self.close_action.is_some(){return Err(ValueError::invariant("clone owner has unresolved close action"))}if !self.closing{let turn=crate::retained_clone::start_retained_close(&mut self.closing,effect);return Ok(reply.complete(turn.result.map(RetainedCloneStep::Progress).map_err(Into::into)))}if self.cursor.terminal_is_empty(){return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let invocation=effect.invocation().ok_or_else(||ValueError::invariant("clone owner close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive||self.close_action.is_some(){return Err(ValueError::invariant("clone owner has an unresolved close action"))}let route=if self.cursor.close_started(){2}else{1};let key=(invocation.identity(),route,body);let mut scope=reply.progress().scope(&mut self.close_action,key)?;let child=scope.borrow()?;let done=if route==1{self.cursor.begin_close_into(effect,child)}else{self.cursor.close_into(body,effect,child)}?;drop(done);Ok(scope.forwarded())}
 pub fn recover_close_into<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let(identity,route,selected_body)=self.close_action.ok_or_else(||ValueError::invariant("clone owner has no original close action"))?;if selected_body!=body||!effect.invocation().is_some_and(|i|i.identity()==identity&&i.mode()==crate::OriginalEffectCallbackMode::Recover){return Err(ValueError::invariant("clone owner close recovery changed invocation"))}let mut scope=reply.progress().scope(&mut self.close_action,(identity,route,selected_body))?;let child=scope.borrow()?;let done=match route{1=>self.cursor.recover_begin_close_into(effect,child),2=>self.cursor.recover_close_into(body,effect,child),_=>Err(ValueError::invariant("clone owner close route changed"))}?;drop(done);Ok(scope.forwarded())}
 pub fn close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing||!self.cursor.close_started()||!self.cursor.requires_original_control(){return self.close_into(body,effect,reply)}let invocation=effect.invocation().ok_or_else(||ValueError::invariant("clone owner original close lacks invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive||self.close_action.is_some(){return Err(ValueError::invariant("clone owner has unresolved original close"))}let key=(invocation.identity(),3,body);let mut scope=reply.progress().scope(&mut self.close_action,key)?;let done=self.cursor.close_original_into(original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 pub fn recover_close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let(identity,route,selected_body)=self.close_action.ok_or_else(||ValueError::invariant("clone owner has no original close action"))?;if route!=3{return self.recover_close_into(body,effect,reply)}if selected_body!=body||!effect.invocation().is_some_and(|i|i.identity()==identity&&i.mode()==crate::OriginalEffectCallbackMode::Recover){return Err(ValueError::invariant("clone owner original recovery changed invocation"))}let mut scope=reply.progress().scope(&mut self.close_action,(identity,route,selected_body))?;let done=self.cursor.recover_close_original_into(original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}


}
impl<T:RetainedClone> Drop for RetainedCloneOwner<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"typed clone cursor requires original partial-owner closure");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.cursor)}}}}
#[doc(hidden)]
pub struct RetainedCloneOwnerRetirement<T:RetainedClone>{owner:RetainedCloneOwner<T>,reply:ManuallyDrop<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>,action:Option<(crate::OriginalEffectInvocationIdentity,bool,usize)>}
impl<T:RetainedClone> RetainedCloneOwnerRetirement<T>{
 fn relay<'reply>(&mut self,mut original:Option<&mut crate::OriginalRetirementCloseLoan<'_>>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>,recover:bool)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{let invocation=effect.invocation().ok_or_else(||ValueError::invariant("clone owner retirement lacks original invocation"))?;let identity=invocation.identity();let mode=invocation.mode();if recover{if !self.action.is_some_and(|(id,_,selected)|id==identity&&selected==body)||mode!=crate::OriginalEffectCallbackMode::Recover{return Err(ValueError::invariant("clone owner retirement recovery changed invocation"))}}else{if self.action.is_some()||mode!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("clone owner retirement has unresolved invocation"))}self.action=Some((identity,original.is_some(),body))}let before=effect.performed_work();if self.reply.is_none(){let child=crate::retained_clone::OriginalEffectReply::borrow(&mut self.reply)?;let controlled=self.action.ok_or_else(||ValueError::invariant("clone owner retirement lost route"))?.1;let done=match(recover,controlled){(false,false)=>self.owner.close_into(body,effect,child),(true,false)=>self.owner.recover_close_into(body,effect,child),(false,true)=>self.owner.close_original_into(original.as_deref_mut().ok_or_else(||ValueError::invariant("clone owner retirement lost control"))?,body,effect,child),(true,true)=>self.owner.recover_close_original_into(original.as_deref_mut().ok_or_else(||ValueError::invariant("clone owner retirement lost control"))?,body,effect,child)}?;drop(done)}match self.reply.take(){None=>Ok(reply.pending()),Some(result)=>{self.action=None;let work=effect.performed_work().checked_sub(before).ok_or_else(||ValueError::invariant("clone owner retirement work moved backwards"))?;Ok(reply.complete(result.map(|step|RetirementStep::Progress(step.progress(),work))))}}}
}
impl<T:RetainedClone> RetirementCursor for RetainedCloneOwnerRetirement<T>{
 fn close_into<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.relay(None,body,effect,reply,false)}
 fn recover_close_into<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.relay(None,body,effect,reply,true)}
 fn close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.relay(Some(original),body,effect,reply,false)}
 fn recover_close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.relay(Some(original),body,effect,reply,true)}
 fn requires_original_birth(&self)->bool{self.owner.closing&&self.owner.cursor.close_started()&&self.owner.cursor.requires_original_birth()}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->RetirementStep{match self.owner.cursor.close_original_birth_step(original,grant){crate::RetainedWorkPoll::Pending{work}=>RetirementStep::Pending(work),crate::RetainedWorkPoll::Complete(turn)=>match turn.result{Ok(step)=>RetirementStep::Progress(step.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}}
 fn requires_original_control(&self)->bool{self.owner.closing&&self.owner.cursor.close_started()&&self.owner.cursor.requires_original_control()}

 fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.action.is_some_and(|(_,_,selected)|selected!=body){return Err(ValueError::invariant("clone owner retirement body changed"))}self.owner.selected_close_demand(body)}
 fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{if self.action.is_some_and(|(_,_,selected)|selected!=body){return Err(ValueError::invariant("clone owner retirement body changed"))}self.owner.selected_close_work_demand(body)}
 fn terminal_is_empty(&self)->bool{self.action.is_none()&&self.reply.is_none()&&self.owner.closing&&self.owner.terminal_is_empty()}
 fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.owner.selected_close_demand(0)?.depth)}
 fn next_work_byte_demand(&self)->Result<usize,ValueError>{Ok(self.owner.selected_close_demand(0)?.copy_bytes)}
 fn next_selected_work_byte_demand(&self,body:usize)->Result<usize,ValueError>{Ok(self.owner.selected_close_demand(body)?.copy_bytes)}
 fn next_close_byte_demand(&self)->Option<usize>{self.owner.selected_close_demand(0).ok().map(|demand|demand.release_bytes)}
 fn next_birth_bytes(&self,body:usize)->Option<usize>{self.owner.selected_close_demand(body).ok().map(|demand|demand.capacity_bytes)}
 fn allows_admitted_narrow_work(&self)->bool{true}
 fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(size_of::<Self>())}
}
impl<T:RetainedClone> Drop for RetainedCloneOwnerRetirement<T>{fn drop(&mut self){if self.action.is_none()&&self.reply.is_none(){unsafe{ManuallyDrop::drop(&mut self.reply)}}else{assert!(std::thread::panicking(),"clone owner retirement retains original reply")}}}
impl<T:RetainedClone> RetireOwned for RetainedCloneOwner<T>{type RetirementCursor=RetainedCloneOwnerRetirement<T>;fn retirement_seed(self)->Self::RetirementCursor{RetainedCloneOwnerRetirement{owner:self,reply:ManuallyDrop::new(None),action:None}}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<Self::RetirementCursor>())}fn controlled_retirement_supported()->bool{true}}
